import collections
import enum
from typing import List

try:
    from collections.abc import Coroutine
except ImportError:  # python 3.4
    from backports_abc import Coroutine

__all__ = ('Event',)


@enum.unique
class Event(enum.Enum):
    initiator_connected = 'initiator-connected'
    responder_connected = 'responder-connected'
    disconnected = 'disconnected'


class EventRegistry:
    events = collections.defaultdict(list)  # type: Dict[Event, List[Coroutine]]

    def register(self, event: Event, handler: Coroutine):
        self.events[event].append(handler)

    def get_callbacks(self, event: Event) -> List[Coroutine]:
        return self.events[event]

# Math.DivRem Method (Int64, Int64, Int64)

.NET Framework 4.6 and 4.5

Calculates the quotient of two 64-bit signed integers and also returns the remainder in an output parameter.

Namespace:  System
Assembly:  mscorlib (in mscorlib.dll)

## Syntax

```public static long DivRem(
long a,
long b,
out long result
)
```

#### Parameters

a
Type: System.Int64

The dividend.

b
Type: System.Int64

The divisor.

result
Type: System.Int64

The remainder.

#### Return Value

Type: System.Int64
The quotient of the specified numbers.

## Exceptions

ExceptionCondition
DivideByZeroException

b is zero.

## Remarks

The remainder is calculated by using the modulus operation.

## Examples

The following example demonstrates the DivRem(Int64, Int64, Int64) method.

```using System;

public class Example
{
public static void Main()
{
// Define several positive and negative dividends.
long[] dividends = { Int64.MaxValue, 13952, 0, -14032,
Int64.MinValue };
// Define one positive and one negative divisor.
long[] divisors = { 2000, -2000 };

foreach (long divisor in divisors)
{
foreach (long dividend in dividends)
{
long remainder;
long quotient = Math.DivRem(dividend, divisor, out remainder);
Console.WriteLine(@"{0:N0} \ {1:N0} = {2:N0}, remainder {3:N0}",
dividend, divisor, quotient, remainder);
}
}
}
}
